-- ============================================
-- LUMA — Enrichissement Thématique 13 (Networking) : scénarios longs
-- ============================================

update scenarios set content = '{"characters": {"contact1": "un contact du jour 1", "contact2": "un contact du jour 2"}, "start_node": "n1", "nodes": {"n1": {"speaker": "contact1", "text": "Day one was intense! Did you attend the keynote?", "text_fr": "Le premier jour était intense ! Vous avez assisté au discours d''ouverture ?", "choices": [{"text": "Yes, it really changed my perspective on the industry.", "next": "n2"}, {"text": "I missed it, was stuck in another session — was it good?", "next": "n2b"}]}, "n2": {"speaker": "contact1", "text": "Same here! Let''s grab coffee tomorrow and discuss more.", "text_fr": "Pareil pour moi ! Prenons un café demain pour en discuter davantage.", "choices": [{"text": "I''d love that, see you tomorrow.", "next": "n3"}]}, "n2b": {"speaker": "contact1", "text": "It was excellent — I actually took notes, I can share them with you.", "text_fr": "C''était excellent — j''ai pris des notes, je peux les partager avec vous.", "choices": [{"text": "That would be amazing, thank you.", "next": "n3"}]}, "n3": {"speaker": "contact2", "text": "(day two) I heard you''re the one who asked that great question yesterday!", "text_fr": "(jour deux) J''ai entendu dire que c''est vous qui avez posé cette excellente question hier !", "choices": [{"text": "That was me! Great to meet someone who noticed.", "next": "n4"}, {"text": "Ha, word travels fast here. What did you think of it?", "next": "n4b"}]}, "n4": {"speaker": "contact2", "text": "Your reputation is already growing at this conference! I''d love to discuss a potential project.", "text_fr": "Votre réputation grandit déjà lors de cette conférence ! J''aimerais discuter d''un projet potentiel.", "choices": [{"text": "I''m intrigued, tell me more.", "next": "n5"}]}, "n4b": {"speaker": "contact2", "text": "Honestly, it sparked a great discussion afterward. I''d love your input on something.", "text_fr": "Honnêtement, ça a lancé une super discussion après. J''aimerais votre avis sur quelque chose.", "choices": [{"text": "Happy to help, what''s on your mind?", "next": "n5"}]}, "n5": {"speaker": "contact2", "text": "We''re exploring a partnership in your exact area of expertise.", "text_fr": "On explore un partenariat exactement dans votre domaine d''expertise.", "choices": [{"text": "Let''s exchange contacts and set up a proper call next week.", "next": "end_network"}]}, "end_network": {"speaker": "contact2", "text": "Perfect, this conference has already exceeded my expectations because of this.", "text_fr": "Parfait, cette conférence a déjà dépassé mes attentes grâce à ça.", "end": true, "ending_label": "Réseau étendu, opportunité concrète née 🌟"}}}'::jsonb, is_playable = true
where title = 'Une conférence sur deux jours avec plusieurs rencontres clés'
  and theme_id = (select id from scenario_themes where position = 13 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"exec": "une dirigeante d''entreprise"}, "start_node": "n1", "nodes": {"n1": {"speaker": "exec", "text": "We''re interested in partnering, but we need exclusivity in this region.", "text_fr": "On est intéressés par un partenariat, mais on a besoin d''exclusivité dans cette région.", "choices": [{"text": "We could offer a 12-month exclusive trial period.", "next": "n2"}, {"text": "Exclusivity is tough for us, but we can offer priority terms instead.", "next": "n2b"}, {"text": "Can you tell me more about why exclusivity matters so much to you?", "next": "n2c"}]}, "n2": {"speaker": "exec", "text": "That''s a reasonable compromise. But what happens after the trial period ends?", "text_fr": "C''est un compromis raisonnable. Mais que se passe-t-il après la fin de la période d''essai ?", "choices": [{"text": "We''d renegotiate based on performance, with an option to extend exclusivity.", "next": "n3"}]}, "n2b": {"speaker": "exec", "text": "Priority terms could work if the conditions are strong enough. What would that include?", "text_fr": "Des conditions prioritaires pourraient fonctionner si elles sont assez solides. Ça inclurait quoi ?", "choices": [{"text": "First access to new features, dedicated support, and preferred pricing.", "next": "n3b"}]}, "n2c": {"speaker": "exec", "text": "Fair question — we''ve been burned before by partners spreading themselves too thin.", "text_fr": "Question légitime — on s''est déjà fait avoir par des partenaires trop dispersés.", "choices": [{"text": "I understand — let''s build in commitments that address that concern directly.", "next": "n3c"}]}, "n3": {"speaker": "exec", "text": "That''s fair, gives us both flexibility and protection.", "text_fr": "C''est juste, ça nous donne à tous les deux flexibilité et protection.", "choices": [{"text": "Exactly the balance we''re aiming for.", "next": "n4"}]}, "n3b": {"speaker": "exec", "text": "That''s actually quite compelling — better than full exclusivity in some ways.", "text_fr": "C''est en fait assez convaincant — mieux que l''exclusivité totale à certains égards.", "choices": [{"text": "We think so too, it protects both sides better.", "next": "n4"}]}, "n3c": {"speaker": "exec", "text": "I appreciate you addressing that directly instead of dismissing it.", "text_fr": "J''apprécie que vous abordiez ça directement plutôt que de l''ignorer.", "choices": [{"text": "Trust is the foundation of any good partnership.", "next": "n4"}]}, "n4": {"speaker": "exec", "text": "Alright, I think we have the outline of a real deal here. Let''s draft terms this week.", "text_fr": "D''accord, je pense qu''on a l''esquisse d''un vrai accord ici. Rédigeons les termes cette semaine.", "choices": [{"text": "Excellent, I''ll have our team prepare the paperwork.", "next": "end_deal"}]}, "end_deal": {"speaker": "exec", "text": "Looking forward to a strong partnership ahead.", "text_fr": "J''ai hâte de ce partenariat solide qui s''annonce.", "end": true, "ending_label": "Partenariat négocié avec des bases solides 🤝"}}}'::jsonb, is_playable = true
where title = 'Négocier un partenariat lors de l''événement'
  and theme_id = (select id from scenario_themes where position = 13 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"audience": "le public"}, "start_node": "n1", "nodes": {"n1": {"speaker": "audience", "text": "So, tell us — what problem does your project actually solve?", "text_fr": "Alors, dites-nous — quel problème votre projet résout-il vraiment ?", "choices": [{"text": "It streamlines a process that currently takes hours into just minutes.", "next": "n2"}, {"text": "It addresses a gap that most people don''t even realize exists yet.", "next": "n2b"}]}, "n2": {"speaker": "audience", "text": "Impressive. What makes your approach different from competitors?", "text_fr": "Impressionnant. Qu''est-ce qui rend votre approche différente de la concurrence ?", "choices": [{"text": "We focus on simplicity and user experience above all else.", "next": "n3"}, {"text": "Honestly, we''re not the first, but we execute far better.", "next": "n3b"}]}, "n2b": {"speaker": "audience", "text": "Interesting framing — can you give a concrete example?", "text_fr": "Cadrage intéressant — vous pouvez donner un exemple concret ?", "choices": [{"text": "(share a relatable, specific real-world example)", "next": "n3"}]}, "n3": {"speaker": "audience", "text": "That''s compelling. What''s your biggest challenge right now?", "text_fr": "C''est convaincant. Quel est votre plus grand défi actuellement ?", "choices": [{"text": "Honestly, scaling our team fast enough to meet demand.", "next": "n4"}, {"text": "Convincing traditional players in the industry to adapt.", "next": "n4b"}]}, "n3b": {"speaker": "audience", "text": "Confidence in execution — I like that. What''s holding you back currently?", "text_fr": "De la confiance dans l''exécution — j''aime ça. Qu''est-ce qui vous freine actuellement ?", "choices": [{"text": "Mainly funding to accelerate our growth.", "next": "n4"}]}, "n4": {"speaker": "audience", "text": "That''s a common but solvable challenge. We''d love to learn more after this session.", "text_fr": "C''est un défi courant mais solvable. On aimerait en savoir plus après cette session.", "choices": [{"text": "I''d be thrilled to continue the conversation.", "next": "end_success"}]}, "n4b": {"speaker": "audience", "text": "That resonates — change is hard, but necessary. Let''s talk more afterward.", "text_fr": "Ça résonne — le changement est difficile, mais nécessaire. Parlons-en davantage après.", "choices": [{"text": "I''d really appreciate that.", "next": "end_success"}]}, "end_success": {"speaker": "audience", "text": "(applause) Great presentation, and a promising future ahead!", "text_fr": "(applaudissements) Excellente présentation, et un avenir prometteur !", "end": true, "ending_label": "Présentation réussie, intérêt confirmé 👏"}}}'::jsonb, is_playable = true
where title = 'Présenter son propre projet devant un public'
  and theme_id = (select id from scenario_themes where position = 13 and language_id = (select id from languages where code = 'en'));
